"""Debates sobre sexualidade, gênero e outras condições (sexta leva). Escritos com cuidado: a pergunta ética nunca é se as pessoas são legítimas,
e sim o que devemos a elas e onde há dano real."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
VP = 'Vida pessoal e relações'

DEBATES6 = [
dict(s='fetiches-e-preferencias-sexuais', n='Fetiches e preferências sexuais', t=VP, r='O que torna uma prática sexual aceitável não é ser comum, e sim consentida e sem dano. Onde a linha passa, e onde ela realmente é cruzada.',
 v='Fetiches, práticas e preferências sexuais variam enormemente entre pessoas, e a maioria delas foi, em algum momento, chamada de perversão ou doença. A psiquiatria hoje só trata como transtorno o que causa sofrimento à própria pessoa ou dano a outros. A ética faz a mesma pergunta: há alguém prejudicado?',
 lados=[('O critério: consentimento e dano', ['Entre adultos capazes, informados e livres para dizer não, uma prática sexual não é errada por ser incomum, intensa ou estranha para quem não a compartilha. A repulsa de terceiros não é dano.', 'A história é um aviso: homossexualidade, sexo oral e masturbação já foram “perversões” condenadas com argumentos idênticos aos usados hoje contra outras práticas.', 'Consentimento é um processo: pode ser retirado a qualquer momento, exige capacidade (sobriedade, idade, ausência de coação) e informação sobre riscos.', 'Práticas de risco físico (como as que envolvem dor ou restrição) pedem acordos explícitos e cuidado, como qualquer atividade de risco entre adultos.']),
        ('Onde há dano, e por isso há erro', ['Sem consentimento: qualquer prática imposta, inclusive por manipulação, coação econômica ou aproveitamento de incapacidade.', 'Com quem não pode consentir: crianças, pessoas incapacitadas, animais. Aqui não há debate: o dano e a impossibilidade de consentimento decidem.', 'Quando a preferência só se realiza prejudicando terceiros, como no exibicionismo não consentido ou no voyeurismo sem conhecimento da pessoa observada.', 'Quando causa sofrimento à própria pessoa de forma que ela gostaria de mudar: aí é questão de cuidado e saúde, não de moral.'])],
 c=['Pressão dentro de uma relação (“se me amasse, faria”) mina o consentimento sem violência visível; a ética exige que o não seja fácil de dizer.', 'A pornografia molda preferências, e o que é consentido em cena pode ser simulado; a lição sobre consentimento vale para o consumo também.', 'Há práticas em que o consentimento não basta para quem defende limites ao dano a si mesmo (Mill proibia vender-se como escravo); o debate é sobre onde fica esse limite, e ele é raro.'],
 p=('forte', 'Há consenso entre filósofos e na psiquiatria: o critério moral é consentimento genuíno e ausência de dano a terceiros, não a frequência ou a estranheza da prática. Onde não há consentimento possível (crianças, animais, pessoas incapacitadas) ou onde terceiros são prejudicados, há erro grave, e nisso também não há debate. O que fica em discussão são os casos de consentimento sob pressão sutil, que pedem atenção e não proibição.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'Entre adultos consentindo, não há dano; o que é proibido é o que prejudica outros.'), ('deontologia-kantiana', 'Kant', 'O limite é usar alguém apenas como meio; com consentimento informado, não há uso.'), ('deontologia-de-direitos', 'Direitos', 'Autonomia sobre o próprio corpo, limitada pelo direito dos outros de não serem envolvidos sem consentir.'), ('etica-do-cuidado', 'Cuidado', 'Pergunta pelas condições do consentimento e pelo bem-estar de cada envolvido.'), ('etica-das-virtudes', 'Virtudes', 'Respeito e honestidade entre parceiros; a prática em si não é virtude nem vício.')],
 licoes=['imparcialidade', 'fazer-e-deixar-acontecer', 'vieses-morais'],
 fx=[('Sex and Sexuality (Stanford Encyclopedia)', SEP + 'sex-sexuality/'), ('Consent (Stanford Encyclopedia)', SEP + 'consent/'), ('Paraphilia (Wikipédia)', WE + 'Paraphilia')]),

dict(s='homossexualidade', n='Homossexualidade', t=VP, r='Há algo moralmente errado em relações entre pessoas do mesmo sexo? A filosofia respondeu que não, e vale ver por quê, e o que ainda é devido.',
 v='Relações entre pessoas do mesmo sexo foram criminalizadas em quase todo o mundo até a segunda metade do século XX, e ainda são em dezenas de países. A pergunta ética tem duas partes: há erro na relação em si? E o que a sociedade deve a quem a vive?',
 lados=[('Não há erro na relação', ['O teste básico: há alguém prejudicado? Entre adultos consentindo, não. Toda objeção precisa apontar uma vítima, e nenhuma apontou.', '“Não é natural”: é a falácia naturalista; e o comportamento homossexual é observado em centenas de espécies, o que torna o argumento falso além de inválido.', '“Não gera filhos”: casais inférteis e pessoas que escolhem não ter filhos não são condenados por isso; o critério, aplicado com coerência, condenaria metade da humanidade.', 'A tradição e o nojo: toda discriminação se apoiou neles, e a imparcialidade pergunta qual diferença relevante existe entre um casal e outro. Não há.', 'Despatologização: a psiquiatria retirou a homossexualidade da lista de transtornos em 1973 (APA) e 1990 (OMS), por falta de evidência de disfunção.']),
        ('As objeções restantes, e seus limites', ['Objeções religiosas: valem para quem partilha a fé, e mesmo entre crentes há leituras que as rejeitam; não podem fundar leis em sociedades plurais. Veja ética e religião.', 'Objeções de lei natural: dependem de definir a sexualidade pela procriação, o que a própria tradição não sustenta com coerência.', 'Preocupações com crianças em famílias homoparentais: décadas de estudos não encontram prejuízo; o dano que existe vem do preconceito externo.'])],
 c=['O que resta de debate não é sobre a moral da relação, e sim sobre deveres: reconhecimento legal igual, proteção contra violência, e o conflito entre liberdade religiosa e não discriminação em serviços públicos.', 'Terapias de “conversão” causam dano documentado e são proibidas em vários países, inclusive pelo conselho de psicologia no Brasil.', 'A orientação sexual é um dos eixos das fronteiras da parcialidade; o argumento contra a homofobia é o mesmo contra o racismo: um traço irrelevante tomado como relevante.'],
 p=('forte', 'Há consenso filosófico: não há nada moralmente errado em relações entre adultos do mesmo sexo, porque não há vítima, e todas as objeções apresentadas falham no teste da diferença relevante ou são falácias naturalistas. O que é devido a pessoas homossexuais é o que é devido a qualquer pessoa: igual consideração, igual reconhecimento legal e proteção contra o dano que o preconceito causa.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Sem dano a ninguém e com bem-estar para os envolvidos: nada a objetar; a proibição é que causa sofrimento.'), ('deontologia-kantiana', 'Kant', 'Kant pessoalmente condenou; kantianos de hoje notam que nenhuma pessoa é usada como meio, e a máxima é universalizável.'), ('lei-natural', 'Lei natural', 'A tradição condenou por ligar sexo a procriação; críticos internos e externos mostram a incoerência.'), ('etica-das-virtudes', 'Virtudes', 'O que importa é amor, fidelidade e cuidado, e eles não têm sexo.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber a própria orientação, ninguém aceitaria a discriminação.')],
 licoes=['imparcialidade', 'tribalismo-moral', 'fatos-e-valores', 'expansao-do-circulo-moral'],
 fx=[('Homosexuality (Stanford Encyclopedia)', SEP + 'homosexuality/'), ('Homosexual behavior in animals (Wikipédia)', WE + 'Homosexual_behavior_in_animals'), ('Resolução CFP 01/1999 (Conselho Federal de Psicologia)', 'https://site.cfp.org.br/wp-content/uploads/1999/03/resolucao1999_1.pdf')]),

dict(s='transgeneridade', n='Transgeneridade', t=VP, r='O que devemos a pessoas cuja identidade de gênero não corresponde ao sexo atribuído ao nascer: respeito, reconhecimento e cuidado. E como tratar as perguntas abertas sem transformá-las em negação.',
 v='Pessoas trans existem em todas as culturas registradas. A pergunta ética central não é se a identidade delas é “real”, e sim o que lhes é devido. Há também perguntas práticas e empíricas (esporte, cuidados médicos em adolescentes) que merecem discussão honesta, e que são diferentes da pergunta sobre dignidade.',
 lados=[('O que é devido', ['Igual consideração: ser trans não é uma diferença relevante para nenhum interesse básico; o teste da imparcialidade é o mesmo das outras fronteiras.', 'Reconhecimento: nome, pronome e documentos; negá-los causa sofrimento documentado sem beneficiar ninguém.', 'Proteção: pessoas trans sofrem violência em taxas muito mais altas, e o Brasil está entre os países que mais as matam; o dever de proteção é urgente.', 'Despatologização: a OMS retirou a transgeneridade da lista de transtornos mentais em 2019; o sofrimento, quando existe, vem sobretudo da rejeição e da falta de acesso a cuidado.', 'Cuidado: a evidência disponível indica que o cuidado afirmativo em adultos reduz sofrimento e risco de suicídio; negá-lo tem custo.']),
        ('As perguntas abertas, e como tratá-las', ['Esporte de alto rendimento: há uma tensão real entre inclusão e equidade competitiva em algumas modalidades; a resposta é empírica e por modalidade, não uma negação de identidade.', 'Cuidados em adolescentes: a evidência sobre bloqueadores e hormônios em menores é mais limitada do que em adultos, e países divergem sobre protocolos. Pedir mais evidência é legítimo; usar a dúvida para negar todo cuidado, ou para negar a existência de adolescentes trans, não é.', 'Espaços segregados por sexo: conflitos reais e raros, resolvidos melhor por desenho (privacidade para todos) do que por exclusão.', 'Esses debates são sobre políticas específicas, e nenhum deles autoriza tratar pessoas trans como ameaça ou como erro.'])],
 c=['Separar a pergunta sobre dignidade (resolvida) das perguntas sobre políticas (em aberto em parte) é o que permite discutir sem ferir.', 'Parte da evidência é recente e em revisão; a honestidade exige dizer o que se sabe e o que não se sabe, em vez de certeza dos dois lados.', 'A transfobia é uma das fronteiras da parcialidade: favorece quem tem identidade normativa e despreza quem não tem; o argumento contra ela é o de sempre.'],
 p=('parcial', 'Sobre o que é devido a pessoas trans (igual consideração, reconhecimento, proteção e acesso a cuidado), o peso da razão é claro, e as objeções falham no teste da diferença relevante. Sobre algumas políticas específicas (esporte de elite, protocolos para adolescentes), há perguntas empíricas em aberto, que merecem evidência e debate sem que isso vire negação da identidade ou da dignidade de ninguém.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Dignidade e respeito pela pessoa como ela se entende; negar reconhecimento é tratá-la como meio de um conforto alheio.'), ('utilitarismo-classico', 'Utilitarismo', 'Reconhecimento e cuidado reduzem sofrimento; a rejeição o aumenta, sem benefício a ninguém.'), ('etica-do-cuidado', 'Cuidado', 'Atenção à pessoa concreta e ao que ela precisa, sobretudo quando vulnerável.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber a própria identidade, ninguém aceitaria a exclusão.'), ('etica-das-virtudes', 'Virtudes', 'Respeito e compaixão diante do que não se compreende de dentro.')],
 licoes=['imparcialidade', 'tribalismo-moral', 'probabilidade-e-etica', 'como-discutir-etica'],
 fx=[('Feminist Perspectives on Trans Issues (Stanford Encyclopedia)', SEP + 'feminism-trans/'), ('ICD-11: gender incongruence (OMS)', 'https://www.who.int/standards/classifications/frequently-asked-questions/gender-incongruence-and-transgender-health-in-the-icd'), ('Transgender (Wikipédia)', WE + 'Transgender')]),

dict(s='neurodivergencia-e-outras-condicoes', n='Neurodivergência, intersexo e outras condições', t=VP, r='Autismo, TDAH, intersexo, assexualidade: diferenças que já foram tratadas como defeito. O que a ética diz sobre cada uma, e o que é devido.',
 v='Muitas condições humanas foram, e algumas ainda são, tratadas como doenças a corrigir, mesmo quando quem as tem não sofre com elas, e sim com o modo como é tratado. A ética pergunta, para cada uma: há dano? Para quem? E o que a pessoa quer?',
 lados=[('O que as condições têm em comum', ['Neurodivergência (autismo, TDAH, dislexia): o modelo da neurodiversidade propõe que são variações do funcionamento humano, não defeitos; o sofrimento, quando existe, vem em parte de um mundo desenhado para um só tipo de mente. Isso não nega que algumas pessoas precisem e queiram apoio.', 'Intersexo: pessoas nascidas com características sexuais que não se encaixam nos padrões típicos. Cirurgias “normalizadoras” em bebês, sem necessidade médica e sem consentimento, são condenadas por organizações de direitos humanos e por associações médicas; a decisão deve esperar a própria pessoa.', 'Assexualidade: a ausência ou baixa frequência de atração sexual não é disfunção quando não causa sofrimento; patologizá-la repete o erro feito com a homossexualidade.', 'Em todos os casos, o critério é o mesmo: a capacidade de a pessoa ser prejudicada ou beneficiada não muda com a condição, e o que ela quer para si pesa mais do que o que os outros acham que ela deveria querer.']),
        ('As perguntas que ficam', ['Onde a condição envolve sofrimento intrínseco (dor crônica, incapacidade grave), o modelo da diferença não basta, e o cuidado inclui tratamento; a pessoa decide, quando pode.', 'Quando a pessoa não pode decidir (bebês, incapacidade cognitiva grave), quem decide e com que critério? A regra mais defendida: adiar o irreversível e escolher pelo melhor interesse de quem é afetado, não pelo conforto de terceiros.', 'O modelo da neurodiversidade é contestado para casos de autismo com alto suporte; a resposta razoável é que o modelo e o cuidado não se excluem.'])],
 c=['Diferença e deficiência não são opostos: uma pessoa pode ser diferente, precisar de apoio e ter uma vida boa, tudo ao mesmo tempo. Veja deficiência e ética.', 'O capacitismo e a patologização operam com a mesma estrutura de outras fronteiras: um padrão tomado como norma, e o resto como erro.', 'A linguagem muda, e é parte do cuidado: perguntar como a pessoa quer ser chamada e descrita.'],
 p=('forte', 'Há convergência ética e médica: condições que não causam sofrimento intrínseco não são defeitos, e intervenções irreversíveis em quem não pode consentir, sem necessidade médica, são erradas. O que é devido a todas as pessoas nessas situações é igual consideração, apoio quando quiserem e desenho de um mundo que não trate uma variação como falha. O que fica em aberto são decisões por quem não pode decidir, e aí a regra é adiar o irreversível e decidir pelo interesse de quem é afetado.'),
 teorias=[('sencientismo', 'Sencientismo', 'A capacidade de ser prejudicado ou beneficiado não muda com a condição; é o que conta.'), ('deontologia-kantiana', 'Kant', 'Intervir no corpo de quem não consentiu, para conforto alheio, trata a pessoa como meio.'), ('etica-do-cuidado', 'Cuidado', 'Responder ao que a pessoa precisa e quer, não ao que o padrão espera.'), ('utilitarismo-classico', 'Utilitarismo', 'Patologizar quem não sofre causa sofrimento; apoiar quem quer apoio o reduz.'), ('etica-das-virtudes', 'Virtudes', 'Hospitalidade à diferença como virtude de uma comunidade.')],
 licoes=['deficiencia-e-etica', 'igualdade-humana', 'bioetica', 'imparcialidade'],
 fx=[('Neurodiversity (Wikipédia)', WE + 'Neurodiversity'), ('Intersex human rights (Wikipédia)', WE + 'Intersex_human_rights'), ('Disability: Definitions and Models (Stanford Encyclopedia)', SEP + 'disability/')]),
]
assert len({d['s'] for d in DEBATES6}) == len(DEBATES6)
